import type { ReactElement } from "react";
import {
  CtaButton,
  EMAIL_COLORS,
  EmailLayout,
  FactRow,
  Spacer,
} from "./layout";
import { formatPaise } from "@/lib/money";
import type { TemplateName } from "@/domain/email";

/**
 * Transactional email templates (plan §13.3).
 *
 * Every template: participant display name, public codes, amount snapshot,
 * clear status language, dashboard link, support contact. No secrets, no raw
 * DB ids, no payment-instrument data. Each has a plain-text alternative
 * generated by the renderer.
 */

export interface TemplateData {
  displayName: string;
  publicOrderCode?: string;
  publicPassCode?: string;
  productName?: string;
  qrDataUrl?: string;
  publicRegistrationCode?: string;
  amountPaise?: number;
  currency?: string;
  eventName?: string;
  eventDateTime?: string;
  venue?: string;
  teamName?: string;
  teamMembers?: string[];
  providerReference?: string;
  ticketCode?: string;
  topic?: string;
  resolutionNote?: string;
  roleName?: string;
  // Group-entry notification fields (public /group-entry form).
  entryCode?: string;
  leadName?: string;
  entryEmail?: string;
  phone?: string;
  college?: string;
  groupSize?: number;
  notes?: string;
  dashboardUrl: string;
  supportEmail: string;
}

function StatusBanner({ text, color }: { text: string; color: string }) {
  return (
    <div
      style={{
        backgroundColor: color,
        border: `3px solid ${EMAIL_COLORS.black}`,
        padding: "10px 14px",
        fontFamily: "Arial, Helvetica, sans-serif",
        fontSize: 15,
        fontWeight: 900,
        textTransform: "uppercase",
      }}
    >
      {text}
    </div>
  );
}

function Support({ supportEmail }: { supportEmail: string }) {
  return (
    <p style={{ fontSize: 13, color: "#333333" }}>
      Need help? Contact the help desk at <b>{supportEmail}</b> or visit the
      Student Centre. Quote your public code — never share passwords or
      payment details.
    </p>
  );
}

export function renderTemplate(
  name: TemplateName,
  data: TemplateData
): { subject: string; element: ReactElement } {
  const d = data;
  switch (name) {
    case "delegate-pass-confirmation":
      return {
        subject: `Your PULSE 2026 Delegate Card & Gate QR is confirmed (${d.publicPassCode ?? d.publicOrderCode ?? ""})`,
        element: (
          <EmailLayout title="Delegate Card Confirmed">
            <StatusBanner text="Payment Confirmed — Delegate Card Active" color={EMAIL_COLORS.secondary} />
            <Spacer />
            <p>Hi {d.displayName},</p>
            <p>
              Your <b>{d.productName ?? "All-Access Delegate Card"}</b> for PULSE 2026 is confirmed.
              Below is your official Gate Entry QR Code. Present this QR at the campus gates for entry.
            </p>
            <Spacer height={8} />

            {/* Embedded Gate QR Code */}
            {d.qrDataUrl && (
              <div
                style={{
                  textAlign: "center",
                  margin: "16px 0",
                  padding: "16px",
                  backgroundColor: "#ffffff",
                  border: `4px solid ${EMAIL_COLORS.black}`,
                }}
              >
                <p style={{ margin: "0 0 8px 0", fontSize: 13, fontWeight: 900, textTransform: "uppercase" }}>
                  ★ Official Gate Entry QR Card ★
                </p>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={d.qrDataUrl}
                  alt="Gate Entry QR Card"
                  width={220}
                  height={220}
                  style={{
                    display: "inline-block",
                    border: `2px solid ${EMAIL_COLORS.black}`,
                  }}
                />
                {d.publicPassCode && (
                  <p
                    style={{
                      margin: "8px 0 0 0",
                      fontFamily: "monospace",
                      fontSize: 18,
                      fontWeight: 900,
                      letterSpacing: "2px",
                    }}
                  >
                    {d.publicPassCode}
                  </p>
                )}
                <p style={{ margin: "4px 0 0 0", fontSize: 11, fontWeight: "bold", color: "#555555" }}>
                  Scan at Main Gate &amp; Pro-Show Arena
                </p>
              </div>
            )}

            {d.publicPassCode && <FactRow label="Card Code" value={d.publicPassCode} />}
            {d.publicOrderCode && <FactRow label="Order" value={d.publicOrderCode} />}
            {d.amountPaise !== undefined && (
              <FactRow label="Amount" value={`${formatPaise(d.amountPaise)} ${d.currency ?? "INR"}`} />
            )}
            {d.providerReference && <FactRow label="Payment Ref" value={d.providerReference} />}
            <Spacer />
            <CtaButton href={d.dashboardUrl} label="View Card on Dashboard" />
            <Spacer />
            <p style={{ fontSize: 13, color: "#d32f2f", fontWeight: "bold" }}>
              ⚠ Anyone with your QR can enter. Do not share or forward this code to others.
            </p>
            <Support supportEmail={d.supportEmail} />
          </EmailLayout>
        ),
      };

    case "event-registration-confirmation": {
      const codeSuffix = d.publicRegistrationCode ?? d.publicOrderCode;
      return {
        subject: `Registration Confirmed: ${d.eventName ?? "PULSE 2026 Event"}${codeSuffix ? ` (${codeSuffix})` : ""}`,
        element: (
          <EmailLayout title="Registration Confirmed">
            <StatusBanner text="Payment Confirmed — You're Registered!" color={EMAIL_COLORS.secondary} />
            <Spacer />
            <p>Hi {d.displayName},</p>
            <p>
              Your registration for <b>{d.eventName ?? "the event"}</b> at PULSE 2026 is confirmed.
              {d.teamName ? <> Registered under team <b>{d.teamName}</b>.</> : null}
            </p>
            <Spacer height={8} />
            {d.eventName && <FactRow label="Event" value={d.eventName} />}
            {d.publicRegistrationCode && (
              <FactRow label="Registration Code" value={d.publicRegistrationCode} />
            )}
            {d.publicOrderCode && <FactRow label="Order ID" value={d.publicOrderCode} />}
            {d.eventDateTime && <FactRow label="Schedule / Time" value={d.eventDateTime} />}
            {d.venue && <FactRow label="Venue" value={d.venue} />}
            {d.teamName && <FactRow label="Team Name" value={d.teamName} />}
            {d.teamMembers && d.teamMembers.length > 0 && (
              <FactRow label="Team Members" value={d.teamMembers.join(", ")} />
            )}
            {d.amountPaise !== undefined && (
              <FactRow label="Amount Paid" value={`${formatPaise(d.amountPaise)} ${d.currency ?? "INR"}`} />
            )}
            {d.providerReference && <FactRow label="Payment Ref" value={d.providerReference} />}
            <Spacer />
            <CtaButton href={d.dashboardUrl} label="View Registration on Dashboard" />
            <Spacer />
            <p style={{ fontSize: 13, color: "#333333" }}>
              Please arrive at the venue 15 minutes prior to the start time with your student ID and Registration Code.
            </p>
            <Support supportEmail={d.supportEmail} />
          </EmailLayout>
        ),
      };
    }

    case "team-member-registration": {
      const codeSuffix = d.publicRegistrationCode ?? d.teamName;
      return {
        subject: `You're registered for ${d.eventName ?? "a PULSE event"}${codeSuffix ? ` (${codeSuffix})` : ""}`,
        element: (
          <EmailLayout title="Team Registration" accent={EMAIL_COLORS.muted}>
            <StatusBanner text="Team Registration Confirmed" color={EMAIL_COLORS.secondary} />
            <Spacer />
            <p>Hi {d.displayName},</p>
            <p>
              You have been registered as a team member for{" "}
              <b>{d.eventName ?? "an event"}</b>
              {d.teamName ? <> in team <b>{d.teamName}</b></> : null}. Your
              team captain completed the registration and payment.
            </p>
            <Spacer height={8} />
            {d.eventName && <FactRow label="Event" value={d.eventName} />}
            {d.publicRegistrationCode && (
              <FactRow label="Registration Code" value={d.publicRegistrationCode} />
            )}
            {d.teamName && <FactRow label="Team Name" value={d.teamName} />}
            {d.eventDateTime && <FactRow label="Schedule / Time" value={d.eventDateTime} />}
            {d.venue && <FactRow label="Venue" value={d.venue} />}
            {d.teamMembers && d.teamMembers.length > 0 && (
              <FactRow label="Team Members" value={d.teamMembers.join(", ")} />
            )}
            <Spacer />
            <CtaButton href={d.dashboardUrl} label="View on Dashboard" />
            <Spacer />
            <p style={{ fontSize: 13, color: "#333333" }}>
              Please arrive at the venue 15 minutes prior to the start time with your student ID and Registration Code.
            </p>
            <Support supportEmail={d.supportEmail} />
          </EmailLayout>
        ),
      };
    }

    case "payment-received-processing":
      return {
        subject: "Payment received — we're confirming your registration",
        element: (
          <EmailLayout title="Payment Processing" accent={EMAIL_COLORS.secondary}>
            <StatusBanner text="Payment received — confirming" color={EMAIL_COLORS.muted} />
            <Spacer />
            <p>Hi {d.displayName},</p>
            <p>
              We received your payment and are confirming it with the payment
              provider. This usually takes a few minutes. You do not need to
              pay again.
            </p>
            <Spacer height={8} />
            {d.publicOrderCode && <FactRow label="Order" value={d.publicOrderCode} />}
            {d.amountPaise !== undefined && (
              <FactRow label="Amount" value={`${formatPaise(d.amountPaise)} ${d.currency ?? "INR"}`} />
            )}
            <Spacer />
            <CtaButton href={d.dashboardUrl} label="Check status" />
            <Spacer />
            <p style={{ fontSize: 13 }}>
              If this takes longer than 30 minutes, contact support with your
              order code.
            </p>
            <Support supportEmail={d.supportEmail} />
          </EmailLayout>
        ),
      };

    case "payment-not-fulfilled":
      return {
        subject: "Action needed: your payment could not be fulfilled",
        element: (
          <EmailLayout title="Payment Needs Review">
            <StatusBanner text="Payment not fulfilled" color={EMAIL_COLORS.accent} />
            <Spacer />
            <p>Hi {d.displayName},</p>
            <p>
              We received your payment but could not complete the
              registration. Our team will review it shortly and contact you —
              you will not lose your money. If you need help sooner, reach out
              to the organizers below.
            </p>
            <Spacer height={8} />
            {d.publicOrderCode && <FactRow label="Order" value={d.publicOrderCode} />}
            {d.amountPaise !== undefined && (
              <FactRow label="Amount" value={`${formatPaise(d.amountPaise)} ${d.currency ?? "INR"}`} />
            )}
            <Spacer />
            <CtaButton href={d.dashboardUrl} label="View details" />
            <Spacer />
            <Support supportEmail={d.supportEmail} />
          </EmailLayout>
        ),
      };

    case "admin-invite":
      return {
        subject: "You've been invited to the PULSE 2026 staff panel",
        element: (
          <EmailLayout title="Staff Invitation" accent={EMAIL_COLORS.muted}>
            <p>Hi {d.displayName},</p>
            <p>
              You have been invited to join the PULSE 2026 organizing panel
              {d.roleName ? <> as <b>{d.roleName}</b></> : null}. Sign in with
              this email and complete onboarding (including two-factor
              authentication) to activate your access.
            </p>
            <Spacer />
            <CtaButton href={d.dashboardUrl} label="Accept invitation" />
            <Spacer />
            <p style={{ fontSize: 13 }}>
              If you were not expecting this invitation, ignore this email.
            </p>
            <Support supportEmail={d.supportEmail} />
          </EmailLayout>
        ),
      };

    case "support-question-received":
      return {
        subject: `We received your question (${d.ticketCode ?? ""})`,
        element: (
          <EmailLayout title="Question Received" accent={EMAIL_COLORS.secondary}>
            <p>Hi {d.displayName},</p>
            <p>
              Thanks for reaching out. Our team will get back to you at this
              email address.
            </p>
            <Spacer height={8} />
            {d.ticketCode && <FactRow label="Ticket" value={d.ticketCode} />}
            {d.topic && <FactRow label="Topic" value={d.topic} />}
            <Spacer />
            <p style={{ fontSize: 13 }}>
              Keep your ticket code handy when following up.
            </p>
            <Support supportEmail={d.supportEmail} />
          </EmailLayout>
        ),
      };

    case "support-question-resolved":
      return {
        subject: `Your question has been resolved (${d.ticketCode ?? ""})`,
        element: (
          <EmailLayout title="Question Resolved" accent={EMAIL_COLORS.secondary}>
            <StatusBanner text="Resolved" color={EMAIL_COLORS.secondary} />
            <Spacer />
            <p>Hi {d.displayName},</p>
            <p>Your question has been resolved by our team.</p>
            {d.resolutionNote && (
              <div
                style={{
                  border: `2px solid ${EMAIL_COLORS.black}`,
                  backgroundColor: EMAIL_COLORS.cream,
                  padding: "12px",
                  fontSize: 14,
                }}
              >
                {d.resolutionNote}
              </div>
            )}
            <Spacer />
            <p style={{ fontSize: 13 }}>
              Still need help? Reply to this email or submit a new question.
            </p>
            <Support supportEmail={d.supportEmail} />
          </EmailLayout>
        ),
      };

    case "group-entry-notification":
      return {
        subject: `New Campus Ambassador application (${d.entryCode ?? ""})`,
        element: (
          <EmailLayout title="New Campus Ambassador Application" accent={EMAIL_COLORS.muted}>
            <StatusBanner text="New campus ambassador application submitted" color={EMAIL_COLORS.secondary} />
            <Spacer />
            <p>
              A new campus ambassador application has been submitted through the public
              portal and is ready to review.
            </p>
            <Spacer height={8} />
            {d.entryCode && <FactRow label="Application Code" value={d.entryCode} />}
            {d.leadName && <FactRow label="Ambassador Name" value={d.leadName} />}
            {d.entryEmail && <FactRow label="Email" value={d.entryEmail} />}
            {d.phone && <FactRow label="Phone" value={d.phone} />}
            {d.college && <FactRow label="College" value={d.college} />}
            {d.groupSize !== undefined && (
              <FactRow label="Contingent Size" value={`${d.groupSize} people`} />
            )}
            {d.notes && (
              <div
                style={{
                  border: `2px solid ${EMAIL_COLORS.black}`,
                  backgroundColor: EMAIL_COLORS.cream,
                  padding: "12px",
                  fontSize: 14,
                }}
              >
                <b>Notes:</b> {d.notes}
              </div>
            )}
            <Spacer />
            <CtaButton href={d.dashboardUrl} label="View on dashboard" />
            <Spacer />
            <Support supportEmail={d.supportEmail} />
          </EmailLayout>
        ),
      };

    default:
      // Exhaustiveness guard — unknown templates render a minimal notice.
      return {
        subject: "PULSE 2026 update",
        element: (
          <EmailLayout title="Update">
            <p>Hi {d.displayName}, there is an update on your PULSE 2026 account.</p>
            <CtaButton href={d.dashboardUrl} label="Open dashboard" />
          </EmailLayout>
        ),
      };
  }
}
